# Türkçe metin işleme fonksiyonları

TÜRK_ALFABESI = "0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz"

def _turk_lower(s: str) -> str:
    """Türkçe kurallarına göre küçük harfe çevir."""
    result = []
    for ch in s:
        code = ord(ch)
        # I -> i
        if code == ord('I'):
            result.append('ı')
            # İ -> i
        elif code == ord('İ'):
            result.append('i')
        elif 'A' <= code <= ord('Z'):
            # Standart küçültme
            result.append(chr(code + 32))
        else:
            result.append(ch)
    return ''.join(result)


def tr_lower(s: str) -> str:
    """Türkçe kurallarına göre küçük harfe çevir."""
    return _turk_lower(s)


def tr_upper(s: str) -> str:
    """Türkçe kurallarına göre büyük harfe çevir."""
    result = []
    for ch in s:
        code = ord(ch)
        # i -> İ
        if code == ord('ı'):
            result.append('I')
            # i -> İ
        elif code == ord('i'):
            result.append('İ')
        elif 'a' <= code <= ord('z'):
            # Standart büyültme
            result.append(chr(code - 32))
        else:
            result.append(ch)
    return ''.join(result)


def tr_sorted(words: list) -> list:
    """Kelimeleri Türk alfabesine göre, büyük/küçük harf farkı gözetmeden sıralar."""
    result = []
    for word in words:
        key = _turk_lower(word)
        result.append((key, word))
    return sorted(result, key=lambda x: x[0])

